SELECT DATE_TRUNC('YEAR', signup_date) AS year_start, DATE_TRUNC('WEEK', signup_date) AS week_start, COUNT_IF(country = 'DE') AS de_events, PERCENTILE_APPROX(credit_limit, 0.9) AS credit_limit_p90, PERCENTILE_APPROX(age, 0.5) AS age_p50, APPROX_PERCENTILE(age, ARRAY(0.25, 0.5, 0.75)) AS age_quartiles, ROUND(SUM(credit_limit) / NULLIF(COUNT(CASE WHEN segment = 'SMB' THEN 1 END), 0), 2) AS credit_limit_per_smb, SIZE(COLLECT_SET(city)) AS num_cities, GROUPING_ID() AS grouping_level FROM customers GROUP BY ROLLUP (DATE_TRUNC('YEAR', signup_date), DATE_TRUNC('WEEK', signup_date))
